bool SoundEvent::Is3D() const
{
bool retVal = false;
auto event = mSystem ? mSystem->GetEventInstance(mID) : nullptr;
if (event)
{
// Get the event description
FMOD::Studio::EventDescription* ed = nullptr;
event->getDescription(&ed);
if (ed)
{
ed->is3D(&retVal); // Is this 3D?
}
}
return retVal;
